<?php require __DIR__.'/../../app/core/bootstrap.php';$u=require_roles(['pengguna']);require __DIR__.'/../../app/helpers/layout.php';render_start('Katalog Skripsi','Repository skripsi yang telah disetujui',$u);dashboard_nav('pengguna');render_mid('Katalog Skripsi','Cari judul, nama mahasiswa, NIM, prodi, atau tahun',$u);$q=trim($_GET['q']??'');$sql="SELECT * FROM repositories WHERE status='publik' AND type='skripsi'";$params=[];if($q!==''){ $sql.=' AND (title LIKE ? OR author LIKE ? OR nim LIKE ? OR study_program LIKE ?)';$like='%'.$q.'%';$params=[$like,$like,$like,$like];}$sql.=' ORDER BY id DESC LIMIT 200';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();?>
<div class="card" style="margin-bottom:18px"><form class="toolbar" method="get"><input class="input search" name="q" value="<?=e($q)?>" placeholder="Cari skripsi..."><button class="btn btn-primary">Cari</button></form></div>
<div class="grid grid-3"><?php foreach($rows as $r):?><article class="card"><span class="badge green">Skripsi Disetujui</span><h3><?=e($r['title'])?></h3><p class="muted"><?=e($r['author'])?> · NIM <?=e($r['nim']??'—')?></p><p><?=e($r['study_program']??'—')?> · <?=e($r['publication_year']??'—')?></p><p class="muted"><?=e(mb_strimwidth($r['abstract']??'Belum ada abstrak.',0,150,'…'))?></p><a class="btn btn-light" href="/pengguna/detail-skripsi/index.php?id=<?=$r['id']?>">Lihat Detail</a></article><?php endforeach;if(!$rows):?><div class="card empty" style="grid-column:1/-1">Skripsi belum tersedia.</div><?php endif;?></div><?php render_end();?>
